/**
 *  A phone with the same id is paired under another key. Pairing never
 *  replaces it without asking, so the user removes it first.
 */
"alreadyPaired";

/**  How the user pairs a new phone. */
export type PairingMethod = 
/**  The phone scans a QR code shown on this computer. */
"qrCode" | 
/**  Both screens show a six-digit code and the user compares them. */
"sas";

/**  Whether the phone was asked to pair. */
export type PairingRequestState = 
/**  Not yet: the phone is not connected, or calls are not ready on it. */
"notAsked" | 
/**  Asked; no answer yet. */
"waiting" | 
/**  The phone shows its user a prompt to pair. */
"asked" | 
/**  The phone has no Bluetooth, or turned calls off. */
"unavailable" | 
/**
 *  The phone cannot show its prompt to pair, as when the user blocked
 *  its notifications: the user pairs from the phone's Bluetooth
 *  settings, picking this computer's Bluetooth name. Pairing stays
 *  open.
 */
"notAllowed" | 
/**  The phone could not ask its user. */
"failed";

/**  Where a pairing attempt currently stands. */
export type PairingState = 
/**  Nothing is happening. */
{ step: "idle" } | 
/**  A QR code is on screen, waiting for a phone to scan it. */
{ step: "qrOffer"; 
/**  The code as an SVG document, black on white so it scans in any theme. */
svg: string; 
/**
 *  Which code of this activation it is, from 1. A new one replaces
 *  it shortly before it expires.
 */
offerNumber: number; 
/**  The name the phone will see for this computer. */
desktopName: string; 
/**  Time left until this offer is replaced. */
expiresInMs: number; 
/**  Length of the offer, for drawing progress. */
lifetimeMs: number; 
/**
 *  Why the last connection the user asked for, to a typed address,
 *  ended. A failed connection does not end the offer.
 */
lastFailure: PairingFailure | null } | 
/**  Looking for phones in pairing mode (code comparison). */
{ step: "searching"; phones: DiscoveredPhone[]; 
/**  Attempts left before the user has to start again. */
attemptsLeft: number; 
/**  Why the previous attempt ended, if one did. */
lastFailure: PairingFailure | null } | 
/**  Opening a connection. */
{ step: "connecting"; method: PairingMethod; phoneName: string | null } | 
/**  Checking the phone's proof. */
{ step: "verifying"; method: PairingMethod; phoneName: string | null } | 
/**  Both screens show this code and the user compares them. */
{ step: "sasCode"; 
/**  Six digits, without spaces. */
code: string; phoneName: string; expiresInMs: number; lifetimeMs: number; 
/**  The user has already confirmed here and we wait for the phone. */
confirmedHere: boolean } | 
/**  The phone is now paired. */
{ step: "paired"; device: Device } | 
/**  Pairing ended without a phone being paired. */
{ step: "failed"; method: PairingMethod; reason: PairingFailure };

/**  The phone's battery. */
export type PhoneBattery = {
	/**  The charge, 0 to 100. */
	percent: number | null,
	/**  Connected to power, also once the battery is full. */
	pluggedIn: boolean,
	/**  Battery saver is on. */
	powerSaver: boolean,
};

/**  A paired phone and its calls. */
export type PhoneCalls = {
	deviceId: string,
	phoneName: string,
	/**  The phone's hands-free link with this desktop. */
	link: CallLink,
	/**  Its calls, the hands-free link's first. */
	calls: CallView[],
	/**  What went wrong last, until it works. */
	problem: CallProblem | null,
};

/**  The phone's cellular connection. */
export type PhoneCellular = {
	/**  Signal bars, 0 to 4. */
	level: number | null,
	network: CellularNetwork | null,
	/**  The carrier's name. */
	operatorName: string | null,
};

/**  What the desktop shows of a phone's status. */
export type PhoneStatus = 
/**
 *  The phone's current status. A part that is `null` is unknown, and
 *  shows as nothing.
 */
{ state: "current"; battery: PhoneBattery | null; 
/**
 *  The cellular connection the phone's status bar shows first;
 *  `null` on a phone without telephony.
 */
cellular: PhoneCellular | null; 
/**  Set while the phone is connected to Wi-Fi. */
wifi: PhoneWifi | null; ringer: RingerMode | null; doNotDisturb: boolean } | 
/**  Connected, and the status is on its way. */
{ state: "waiting" } | 
/**  The user hid the phone's status in this computer's settings. */
{ state: "hidden" } | 
/**  The user turned the status off on the phone. */
{ state: "turnedOff" } | 
/**  The phone does not share its status right now. */
{ state: "unavailable" } | 
/**  The phone's app is too old to share its status. */
{ state: "unsupported" } | 
/**  The phone is not connected, so its status is not current. */
{ state: "disconnected" };

/**  What the UI shows of a phone's status changed. */
export type PhoneStatusChanged = {
	deviceId: string,
	status: PhoneStatus,
};

/**  Which phone to dial. */
export type PhoneTarget = 
/**  A phone from [`PairingState::Searching`], by its id. */
{ kind: "discovered"; id: string } | 
/**
 *  An address typed by the user: `192.168.1.20`, `192.168.1.20:27380` or
 *  `[fd00::2]:27380`. The default port is 27380.
 */
{ kind: "address"; address: string };

/**  The phone's Wi-Fi connection. */
export type PhoneWifi = {
	/**  Signal bars, 0 to 4. */
	level: number | null,
};

/**  What the UI shows of ringing a phone changed. */
export type RingChanged = {
	deviceId: string,
	ring: RingStatus,
};

/**  Why the phone stopped ringing. */
export type RingEnd = 
/**  Someone stopped it on the phone. */
"stoppedOnPhone" | 
/**  A computer stopped it: this one or another one. */
"stoppedFromDesktop" | 
/**  It rang for its full minute. */
"timedOut" | 
/**  It could not keep ringing, for example because a call started. */
"interrupted";

/**  Where ringing stands. */
export type RingPhase = "idle" | 
/**  Asked to ring; the phone has not answered yet. */
"starting" | "ringing" | 
/**  Asked to stop; the phone has not answered yet. */
"stopping";

/**  Why the phone cannot ring, or did not do what the user asked. */
export type RingProblem = 
/**  Ringing is turned off on the phone. */
"turnedOff" | 
/**  The phone can't ring right now, for example during a call. */
"unavailable" | 
/**  The phone's app is too old to ring. */
"unsupported" | 
/**  The phone is not connected. */
"notConnected" | 
/**  The phone has not yet said whether it can ring: shown as nothing. */
"waiting" | 
/**  The phone refused, or did not answer in time. */
"failed";

/**  What the desktop shows of ringing a phone. */
export type RingStatus = {
	phase: RingPhase,
	/**  Why the phone cannot ring now, or `null` when it can. */
	blocked: RingProblem | null,
	/**  Why the last ring or stop the user asked for did not work. */
	problem: RingProblem | null,
	/**  Why the phone stopped ringing without this computer asking. */
	ended: RingEnd | null,
};

/**  Whether calls and notifications make sound on the phone. */
export type RingerMode = "normal" | "vibrate" | "silent";

/**
 *  What the user chose for the desktop app. Settings missing from the file
 *  take their defaults, so older files keep working.
 */
export type Settings = {
	/**
	 *  Pop-ups show the notification's text, not just the app's name. Off
	 *  by default, because pop-ups pass through the desktop's notification
	 *  service, where other programs can read them.
	 */
	showNotificationText?: boolean,
	/**
	 *  The clipboard is shared with the phones. On by default: each phone
	 *  has its own switch, off until its user turns it on.
	 */
	shareClipboard?: boolean,
	/**
	 *  Text that a password manager marked as secret is shared too. Off by
	 *  default.
	 */
	sharePasswords?: boolean,
	/**
	 *  Files can be sent to the phones and received from them. On by
	 *  default: each phone has its own switch, off until its user turns it
	 *  on.
	 */
	shareFiles?: boolean,
	/**
	 *  The connected phone's battery, signal and sound mode are shown. On
	 *  by default: they are what the phone's own status bar shows.
	 */
	showPhoneStatus?: boolean,
	/**
	 *  The phones' calls ring on this computer, and are taken on it over
	 *  Bluetooth. On by default: nothing happens until the user pairs a
	 *  phone over Bluetooth.
	 */
	useForCalls?: boolean,
};

/**  Why the app could not start, for the page shown instead of the app. */
export type StartupError = {
	/**  What failed, in plain words. */
	message: string,
	/**  What the user can do about it. */
	hint: string,
	/**  The error itself, for a bug report. */
	detail: string,
};

/**  A file transfer with a phone changed. */
export type TransferChanged = {
	deviceId: string,
	event: FileTransferEvent,
};

/**  Which way the files go. */
export type TransferDirection = 
/**  From the phone to this computer. */
"incoming" | 
/**  From this computer to the phone. */
"outgoing";

/**  Why a transfer failed. */
export type TransferFailure = 
/**  Files are turned off on the phone. */
"disabled" | 
/**  Files are turned off on this computer. */
"disabledHere" | 
/**  The phone needs a permission before it can save files. */
"permissionRequired" | 
/**  The receiving device has no room for the files. */
"noSpace" | 
/**  The phone refused the transfer or a part of it. */
"refused" | 
/**  A file to send could not be read. */
"unreadable" | 
/**  A file changed while it was being sent. */
"changed" | 
/**  A received file was damaged on the way. */
"damaged" | 
/**  The phone sent bytes that do not fit the transfer. */
"invalid" | 
/**  A received file could not be saved. */
"writeFailed" | 
/**  The phone stayed away for more than an hour. */
"expired" | 
/**  An unfinished transfer was ended to make room for newer ones. */
"tooManyUnfinished";

/**  One file of a transfer. */
export type TransferFileInfo = {
	/**
	 *  The file's name: as sent, or as saved here, with the number it got
	 *  when the name was taken.
	 */
	name: string,
	size: number,
	/**  The MIME type, or empty when not known. */
	mimeType: string,
	/**  A received file that arrived, which the user can open. */
	saved: boolean,
};

/**  Where a transfer stands. */
export type TransferStatus = 
/**  Not started: the phone is away, not ready, or busy. */
{ kind: "waiting" } | 
/**  Bytes are moving. */
{ kind: "running" } | 
/**  The connection dropped; it goes on when the phone is back. */
{ kind: "interrupted" } | { kind: "completed" } | { kind: "cancelled"; 
/**  Cancelled on the phone rather than here. */
byPhone: boolean } | { kind: "failed"; reason: TransferFailure };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}

